    ('00000000-0017-2008-0003-000000000003','Когтеточка картонная','С кошачьей мятой',1490, 5,'48700178030103',40,'1pc','https://images.unsplash.com/photo-1583511655857-d19b40a7a54e?w=400&q=80'),
    ('00000000-0017-2008-0003-000000000004','Игрушка для кошки мышка','Плюшевая',290, 0,'48700178030104',150,'1pc','https://images.unsplash.com/photo-1574158622682-e40e69881006?w=400&q=80'),
    ('00000000-0017-2008-0003-000000000005','Поводок для собаки 1.5м','Нейлоновый',1290, 0,'48700178030105',80,'1.5m','https://images.unsplash.com/photo-1583337130417-3346a1be7dee?w=400&q=80')
) AS p(id, title, descr, price, disc, barcode, stock, weight, img)
ON CONFLICT (barcode) DO NOTHING;

-- ============================================================
-- 3. Wire products → category + subcategory
-- ============================================================
-- Set subcategory_id by parsing the third UUID segment (catNum)
-- and the fourth segment (subNum) from the product UUID — too fragile.
-- Easier: explicit mapping table by barcode prefix.
UPDATE products
SET subcategory_id = sub.id
FROM subcategories sub
WHERE products.barcode LIKE '4870017%'
  AND sub.slug = CASE substr(products.barcode, 8, 4)
        WHEN '0101' THEN 'vegetables-fruits'
        WHEN '0102' THEN 'meat-sausages'
        WHEN '0103' THEN 'fish'
        WHEN '0104' THEN 'eggs'
        WHEN '0105' THEN 'oils'
        WHEN '0201' THEN 'milk-cream'
        WHEN '0202' THEN 'cheese'
        WHEN '0203' THEN 'cottage'
        WHEN '0204' THEN 'yogurts'
        WHEN '0205' THEN 'butter'
        WHEN '0301' THEN 'sodas'
        WHEN '0302' THEN 'juices'
        WHEN '0303' THEN 'drinking-water'
        WHEN '0304' THEN 'tea-coffee'
        WHEN '0401' THEN 'chocolates'
        WHEN '0402' THEN 'cookies'
        WHEN '0403' THEN 'candies'
        WHEN '0404' THEN 'ice-cream'
        WHEN '0501' THEN 'white-bread'
        WHEN '0502' THEN 'rolls'
        WHEN '0503' THEN 'lavash'
        WHEN '0504' THEN 'croutons'
        WHEN '0601' THEN 'laundry'
        WHEN '0602' THEN 'dishwash'
        WHEN '0603' THEN 'cleaners'
        WHEN '0701' THEN 'shampoo-soap'
        WHEN '0702' THEN 'toothpaste'
        WHEN '0703' THEN 'paper'
        WHEN '0704' THEN 'body-care'
        WHEN '0801' THEN 'dog-food'
        WHEN '0802' THEN 'cat-food'
        WHEN '0803' THEN 'pet-care'
      END;

-- Wire products → top-level category via product_categories.
INSERT INTO product_categories (product_id, category_id)
SELECT p.id, c.id
FROM products p
JOIN categories c ON c.slug = CASE substr(p.barcode, 8, 2)
        WHEN '01' THEN 'azyk-tulik'
        WHEN '02' THEN 'sut-onimderi'
        WHEN '03' THEN 'susyndtar'
        WHEN '04' THEN 'tattiler'
        WHEN '05' THEN 'nan-onimderi'
        WHEN '06' THEN 'turmystyk-himia'
        WHEN '07' THEN 'gigena'
        WHEN '08' THEN 'ui-zhanuar'
      END
WHERE p.barcode LIKE '4870017%'
ON CONFLICT DO NOTHING;

-- ============================================================
-- 4. INVENTORY — make every store stock the new catalog
-- ============================================================
INSERT INTO inventory (store_id, product_id, quantity)
SELECT s.id, p.id, p.stock
FROM stores s
CROSS JOIN products p
WHERE p.barcode LIKE '4870017%'
ON CONFLICT DO NOTHING;
